WITH base AS (SELECT *, DAY(start_date) AS start_date_day FROM subscriptions WHERE (end_date > '2025-03-01' AND customer_id IS NULL) OR monthly_fee > 140), end_cohort_summary AS (SELECT CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END AS end_cohort, customer_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values FROM base GROUP BY CASE WHEN YEAR(end_date) < 2024 THEN 'before_2024' WHEN YEAR(end_date) = 2024 THEN '2024' ELSE 'after_2024' END, customer_id) SELECT end_cohort, customer_id FROM end_cohort_summary;
